// Checks the C++ Wifi classes against libwifi:
//  1. frames generated by both are byte-for-byte identical
//  2. every frame of a capture parses to the same values in both
//  3. a few things libwifi did not cover (RSN/EAPOL builders, radiotap)
//
//   ./WifiTests [capture.pcapng]

#include <Wifi/Wifi.h>
#include <Constants/WifiDefenitions.h>

#include <algorithm>
#include <cstring>
#include <iostream>
#include <map>

#include <pcap/pcap.h>

extern "C" {
#include <libwifi.h>
}

static int g_failures = 0;
static int g_checks = 0;

#define CHECK(cond, what)                                                         \
	do                                                                            \
	{                                                                             \
		g_checks++;                                                               \
		if (!(cond))                                                              \
		{                                                                         \
			g_failures++;                                                         \
			std::cerr << "FAIL " << __LINE__ << ": " << what << std::endl;        \
		}                                                                         \
	} while (0)

static std::string hex(std::span<const uint8_t> data)
{
	std::string out;
	char buf[4];
	for (uint8_t b : data)
	{
		std::snprintf(buf, sizeof(buf), "%02x", b);
		out += buf;
	}
	return out;
}

static void checkBytes(const std::vector<uint8_t>& ours, const std::vector<uint8_t>& theirs, const std::string& what)
{
	CHECK(ours == theirs, what << "\n  ours:    " << hex(ours) << "\n  libwifi: " << hex(theirs));
}

static const uint8_t AP[6] = {0x10, 0x20, 0x30, 0x40, 0x50, 0x60};
static const uint8_t STA[6] = {0x02, 0xaa, 0xbb, 0xcc, 0xdd, 0xee};
static const Wifi::MacAddress AP_MAC = Wifi::toMac(AP);
static const Wifi::MacAddress STA_MAC = Wifi::toMac(STA);

/*------------*/
/* GENERATORS */
/*------------*/

static void testGenerators()
{
	// Probe request, as ConnectionHandler::getNetworkInfo builds it
	{
		libwifi_probe_req req = {};
		libwifi_create_probe_req(&req, BROADCAST_MAC_ADDRESS, STA, BROADCAST_MAC_ADDRESS, "HomeNet", 1);
		std::vector<uint8_t> theirs(libwifi_get_probe_req_length(&req));
		libwifi_dump_probe_req(&req, theirs.data(), theirs.size());
		libwifi_free_probe_req(&req);

		auto ours = Wifi::Probe::Request::create(Wifi::BROADCAST, STA_MAC, Wifi::BROADCAST, "HomeNet", 1).build();
		checkBytes(ours, theirs, "probe request");
		CHECK(ours.back() == 1, "probe request: channel is the last byte");
	}

	// Authentication, as ConnectionHandler::authenticateNetwork builds it
	{
		libwifi_auth auth = {};
		libwifi_create_auth(&auth, AP, STA, AP, AUTH_OPEN, TRANSACTION_SEQUENCE_REQ, AUTH_SUCCESS);
		std::vector<uint8_t> theirs(libwifi_get_auth_length(&auth));
		libwifi_dump_auth(&auth, theirs.data(), theirs.size());
		libwifi_free_auth(&auth);

		auto ours = Wifi::Auth::create(AP_MAC, STA_MAC, AP_MAC).build();
		checkBytes(ours, theirs, "auth");
	}

	// Association request with rates + RSN, as associateNetwork builds it
	{
		const std::vector<uint8_t> rates = {0x82, 0x84, 0x8b, 0x96, 0x0c, 0x12, 0x18, 0x24};
		libwifi_assoc_req assoc = {};
		libwifi_create_assoc_req(&assoc, AP, STA, AP, "HomeNet", 6);
		libwifi_quick_add_tag(&assoc.tags, TAG_SUPP_RATES, rates.data(), rates.size());
		libwifi_quick_add_tag(&assoc.tags, TAG_RSN, RSN_WPA2, RSN_INFO_SIZE);
		std::vector<uint8_t> theirs(libwifi_get_assoc_req_length(&assoc));
		libwifi_dump_assoc_req(&assoc, theirs.data(), theirs.size());
		libwifi_free_assoc_req(&assoc);

		auto request = Wifi::Assoc::Request::create(AP_MAC, STA_MAC, AP_MAC, "HomeNet", 6);
		request.tags.add(Wifi::TagNumber::SupportedRates, rates);
		request.tags.add(Wifi::TagNumber::Rsn, std::span<const uint8_t>(RSN_WPA2, RSN_INFO_SIZE));
		checkBytes(request.build(), theirs, "assoc request");
		CHECK(request.length() == theirs.size(), "assoc request length");
	}

	// Reassociation request
	{
		const uint8_t oldAp[6] = {1, 2, 3, 4, 5, 6};
		libwifi_reassoc_req req = {};
		libwifi_create_reassoc_req(&req, AP, STA, AP, oldAp, "HomeNet", 11);
		std::vector<uint8_t> theirs(libwifi_get_reassoc_req_length(&req));
		libwifi_dump_reassoc_req(&req, theirs.data(), theirs.size());
		libwifi_free_reassoc_req(&req);

		auto ours = Wifi::Assoc::Request::createReassoc(AP_MAC, STA_MAC, AP_MAC, Wifi::toMac(oldAp), "HomeNet", 11).build();
		checkBytes(ours, theirs, "reassoc request");
	}

	// Association response
	{
		libwifi_assoc_resp resp = {};
		libwifi_create_assoc_resp(&resp, STA, AP, AP, 6);
		std::vector<uint8_t> theirs(libwifi_get_assoc_resp_length(&resp));
		libwifi_dump_assoc_resp(&resp, theirs.data(), theirs.size());
		libwifi_free_assoc_resp(&resp);

		auto ours = Wifi::Assoc::Response::create(STA_MAC, AP_MAC, AP_MAC, 6).build();
		checkBytes(ours, theirs, "assoc response");
	}

	// Beacon and probe response (same timestamp in both)
	{
		libwifi_beacon beacon = {};
		libwifi_create_beacon(&beacon, BROADCAST_MAC_ADDRESS, AP, AP, "HomeNet", 6);
		beacon.fixed_parameters.timestamp = 0x1122334455667788ULL;
		std::vector<uint8_t> theirs(libwifi_get_beacon_length(&beacon));
		libwifi_dump_beacon(&beacon, theirs.data(), theirs.size());
		libwifi_free_beacon(&beacon);

		auto ours = Wifi::Beacon::create(Wifi::BROADCAST, AP_MAC, AP_MAC, "HomeNet", 6);
		ours.fixed.timestamp = 0x1122334455667788ULL;
		checkBytes(ours.build(), theirs, "beacon");
	}
	{
		libwifi_probe_resp resp = {};
		libwifi_create_probe_resp(&resp, STA, AP, AP, "HomeNet", 6);
		resp.fixed_parameters.timestamp = 42;
		std::vector<uint8_t> theirs(libwifi_get_probe_resp_length(&resp));
		libwifi_dump_probe_resp(&resp, theirs.data(), theirs.size());
		libwifi_free_probe_resp(&resp);

		auto ours = Wifi::Probe::Response::create(STA_MAC, AP_MAC, AP_MAC, "HomeNet", 6);
		ours.fixed.timestamp = 42;
		checkBytes(ours.build(), theirs, "probe response");
	}

	// Deauthentication / disassociation
	{
		libwifi_deauth deauth = {};
		libwifi_create_deauth(&deauth, AP, STA, AP, REASON_STA_LEAVING);
		std::vector<uint8_t> theirs(libwifi_get_deauth_length(&deauth));
		libwifi_dump_deauth(&deauth, theirs.data(), theirs.size());
		libwifi_free_deauth(&deauth);

		auto ours = Wifi::Auth::Deauth::create(AP_MAC, STA_MAC, AP_MAC, Wifi::ReasonCode::StaLeaving).build();
		checkBytes(ours, theirs, "deauth");
	}
	{
		libwifi_disassoc disassoc = {};
		libwifi_create_disassoc(&disassoc, AP, STA, AP, REASON_STA_LEAVING_BSS);
		std::vector<uint8_t> theirs(libwifi_get_disassoc_length(&disassoc));
		libwifi_dump_disassoc(&disassoc, theirs.data(), theirs.size());
		libwifi_free_disassoc(&disassoc);

		auto ours = Wifi::Auth::Deauth::create(AP_MAC, STA_MAC, AP_MAC, Wifi::ReasonCode::StaLeavingBss, true).build();
		checkBytes(ours, theirs, "disassoc");
	}

	// Radiotap header, as PacketHandler::addRadioTap builds it
	for (uint8_t channel : {1, 6, 13})
	{
		libwifi_radiotap_info info = {};
		info.present = (1 << IEEE80211_RADIOTAP_FLAGS) | (1 << IEEE80211_RADIOTAP_CHANNEL);
		info.flags = 0x00;
		info.channel.freq = 2412 + 5 * (channel - 1);
		info.channel.flags = 0x00a0;
		char header[LIBWIFI_MAX_RADIOTAP_LEN] = {0};
		const size_t len = libwifi_create_radiotap(&info, header);
		std::vector<uint8_t> theirs(header, header + len);

		auto ours = Wifi::Radiotap::buildForChannel(Wifi::channelToFrequency(channel));
		checkBytes(ours, theirs, "radiotap ch " + std::to_string(channel));
		CHECK(ours.size() == RADIO_TAP_HEADER_SIZE, "radiotap size is 14");
	}
}

/*---------------*/
/* EXTRA (OURS)  */
/*---------------*/

static void testBuilders()
{
	// RsnInfo::create gives the same 20 bytes as RSN_WPA2 (AKM PSK, CCMP)
	{
		std::vector<uint8_t> expected(RSN_WPA2, RSN_WPA2 + RSN_INFO_SIZE);
		expected[AKM_TYPE_INDEX] = 2; // what setSecurity writes for AKM PSK
		auto rsn = Wifi::Wpa::RsnInfo::create(Wifi::Wpa::CipherSuite::Ccmp128, Wifi::Wpa::CipherSuite::Ccmp128,
			Wifi::Wpa::AkmSuite::Psk);
		checkBytes(rsn.build(), expected, "RsnInfo::create");

		auto parsed = Wifi::Wpa::RsnInfo::parse(expected);
		CHECK(parsed && parsed->build() == expected, "RsnInfo round trip");
		CHECK(parsed && parsed->flags() == (Wifi::Wpa::Flag::Wpa2 | Wifi::Wpa::Flag::AkmPsk |
			Wifi::Wpa::Flag::GroupCcmp128 | Wifi::Wpa::Flag::PairwiseCcmp128), "RsnInfo flags");
	}

	// EAPOL-Key M2: same bytes as the EapolFrame ConnectionHandler sends
	{
		EapolFrame eapol{.keyDesc = {.replayCounter = htobe64(7)}};
		eapol.frameHeader.seqControl = static_cast<uint16_t>(0x123 << 4);
		eapol.keyDesc.keyInfo = htons(INFORMATION_FLAG_M2);
		for (size_t i = 0; i < NONCE_SIZE; i++)
			eapol.keyDesc.nonce[i] = static_cast<uint8_t>(i);
		memcpy(eapol.keyDesc.keyData, RSN_WPA2, RSN_INFO_SIZE);
		memset(eapol.keyDesc.mic, 0xAB, sizeof(eapol.keyDesc.mic));
		memcpy(eapol.frameHeader.addr1, AP, 6);
		memcpy(eapol.frameHeader.addr2, STA, 6);
		memcpy(eapol.frameHeader.addr3, AP, 6);
		std::vector<uint8_t> theirs(reinterpret_cast<uint8_t*>(&eapol), reinterpret_cast<uint8_t*>(&eapol) + sizeof(eapol));

		Wifi::Wpa::EapolKey key;
		key.keyInformation = INFORMATION_FLAG_M2;
		key.replayCounter = 7;
		for (size_t i = 0; i < key.nonce.size(); i++)
			key.nonce[i] = static_cast<uint8_t>(i);
		key.mic.assign(16, 0xAB);
		key.keyData = {static_cast<uint8_t>(Wifi::TagNumber::Rsn), RSN_INFO_SIZE};
		key.keyData.insert(key.keyData.end(), RSN_WPA2, RSN_WPA2 + RSN_INFO_SIZE);
		checkBytes(key.buildDataFrame(AP_MAC, STA_MAC, 0x123), theirs, "EAPOL M2 data frame");
		CHECK(key.message() == Wifi::Wpa::HandshakeMessage::M2, "M2 classified");

		// MIC position: what CryptoManager::setMic fills in
		const auto eapolBytes = key.build();
		CHECK(eapolBytes[Wifi::Wpa::EapolKey::micOffset()] == 0xAB &&
			eapolBytes[Wifi::Wpa::EapolKey::micOffset() - 1] == 0, "micOffset");

		// Parse back from a frame with radiotap
		auto raw = key.buildDataFrame(AP_MAC, STA_MAC, 1);
		Wifi::Radiotap::prepend(raw, {});
		auto frame = Wifi::Frame::parse(raw);
		auto back = frame ? Wifi::Wpa::EapolKey::parse(*frame) : std::nullopt;
		CHECK(back && back->build() == key.build(), "EAPOL round trip");
	}

	// Handshake classification for every message libwifi knew
	{
		const std::pair<uint16_t, Wifi::Wpa::HandshakeMessage> cases[] = {
			{EAPOL_KEY_INFO_M1, Wifi::Wpa::HandshakeMessage::M1},
			{EAPOL_KEY_INFO_M2, Wifi::Wpa::HandshakeMessage::M2},
			{EAPOL_KEY_INFO_M3, Wifi::Wpa::HandshakeMessage::M3},
			{EAPOL_KEY_INFO_M4, Wifi::Wpa::HandshakeMessage::M4},
		};
		for (auto [info, expected] : cases)
		{
			Wifi::Wpa::EapolKey key;
			key.keyInformation = info;
			if (expected == Wifi::Wpa::HandshakeMessage::M2)
				key.nonce[0] = 1;
			CHECK(key.message() == expected, "classify key info " << std::hex << info << std::dec);
			CHECK(static_cast<int>(expected) == (expected == Wifi::Wpa::HandshakeMessage::M1 ? HANDSHAKE_M1 :
				expected == Wifi::Wpa::HandshakeMessage::M2 ? HANDSHAKE_M2 :
				expected == Wifi::Wpa::HandshakeMessage::M3 ? HANDSHAKE_M3 : HANDSHAKE_M4), "enum values");
		}
	}

	// Radiotap with several presence words and per-antenna namespaces
	// (what mt76 delivers)
	{
		const std::vector<uint8_t> header = {
			0x00, 0x00, 0x24, 0x00,             // version, pad, len 36
			0x2f, 0x40, 0x00, 0xa0,             // TSFT FLAGS RATE CHANNEL ANTSIGNAL RXFLAGS, ns, ext
			0x20, 0x08, 0x00, 0xa0,             // ANTSIGNAL ANTENNA, ns, ext
			0x20, 0x08, 0x00, 0x00,             // ANTSIGNAL ANTENNA
			0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // pad to 8 + nothing (TSFT at 16)
		};
		std::vector<uint8_t> rt = {0x00, 0x00, 0x00, 0x00, 0x2f, 0x48, 0x00, 0xa0, 0x20, 0x08, 0x00, 0xa0, 0x20, 0x08, 0x00, 0x00};
		Wifi::ByteWriter w(rt);
		w.le64(0x0102030405060708ULL); // TSFT (offset 16, aligned)
		w.u8(0x10);                    // flags: FCS
		w.u8(0x0c);                    // rate 6 Mbps
		w.le16(5180);                  // channel freq
		w.le16(0x0140);                // channel flags
		w.u8(static_cast<uint8_t>(-40)); // signal
		w.u8(0);                       // pad for rx flags
		w.le16(0);                     // rx flags (bit 14)
		w.u8(static_cast<uint8_t>(-42)); w.u8(0); // antenna 0 signal, number
		w.u8(static_cast<uint8_t>(-45)); w.u8(1); // antenna 1 signal, number
		rt[2] = static_cast<uint8_t>(rt.size());
		(void)header;

		auto info = Wifi::Radiotap::parse(rt);
		CHECK(info.has_value(), "multi-namespace radiotap parses");
		if (info)
		{
			CHECK(info->present.size() == 3, "3 presence words");
			CHECK(info->tsft == 0x0102030405060708ULL, "tsft");
			CHECK(info->hasFcs(), "fcs flag");
			CHECK(info->rate == 0x0c, "rate");
			CHECK(info->channel && info->channel->frequency == 5180 && info->channel->number == 36, "channel 36");
			CHECK(info->signal == -40, "combined signal");
			CHECK(info->antennas.size() == 2, "two antennas");
			if (info->antennas.size() == 2)
			{
				CHECK(info->antennas[0].signal == -42 && info->antennas[0].number == 0, "antenna 0");
				CHECK(info->antennas[1].signal == -45 && info->antennas[1].number == 1, "antenna 1");
			}
		}
	}

	// Tags: set replaces in place, remove, vendor lookup, truncation
	{
		Wifi::Tags tags;
		tags.add(Wifi::TagNumber::Ssid, "a");
		tags.add(Wifi::TagNumber::DsParameter, static_cast<uint8_t>(1));
		tags.set(Wifi::TagNumber::Ssid, "bb");
		CHECK(tags.all()[0].data.size() == 2 && tags.size() == 2, "set replaces in place");
		const std::vector<uint8_t> wps = {0x00, 0x50, 0xF2, 0x04, 0x10};
		tags.add(Wifi::TagNumber::VendorSpecific, wps);
		CHECK(tags.findVendor(Wifi::Wpa::OUI_MICROSOFT, Wifi::Wpa::MICROSOFT_TYPE_WPS) != nullptr, "vendor lookup");
		CHECK(tags.remove(Wifi::TagNumber::DsParameter) == 1 && !tags.contains(Wifi::TagNumber::DsParameter), "remove");
		auto bytes = tags.serialize();
		bytes.pop_back();
		auto cut = Wifi::Tags::parse(bytes);
		CHECK(!cut.complete() && cut.size() == 1, "truncated tag dropped");
		// zero-length SSID (wildcard) is a valid tag
		const std::vector<uint8_t> wildcard = {0x00, 0x00, 0x01, 0x01, 0x82};
		CHECK(Wifi::Tags::parse(wildcard).size() == 2, "zero-length tag kept");
	}
}

/*-----------------*/
/* CAPTURE COMPARE */
/*-----------------*/

static std::map<std::string, int> g_stats;

static void compareFrame(const uint8_t* data, size_t len)
{
	libwifi_frame theirs = {};
	const int theirRet = libwifi_get_wifi_frame(&theirs, data, len, 1);
	auto ours = Wifi::Frame::parse(std::span(data, len));

	if (theirRet != 0)
	{
		g_stats["libwifi rejected"]++;
		if (ours)
			g_stats["libwifi rejected, ours parsed"]++;
		return;
	}
	CHECK(ours.has_value(), "frame libwifi parsed but we did not");
	if (!ours)
	{
		libwifi_free_wifi_frame(&theirs);
		return;
	}

	g_stats["frames"]++;
	CHECK(static_cast<int>(ours->type()) == theirs.frame_control.type, "type");
	CHECK(ours->subtype() == theirs.frame_control.subtype, "subtype");
	CHECK(ours->length() == theirs.len, "len");
	CHECK(ours->isRetry() == theirs.frame_control.flags.retry, "retry flag");

	if (ours->type() == Wifi::FrameType::Control)
	{
		g_stats["control"]++;
		libwifi_free_wifi_frame(&theirs);
		return; // libwifi only reads frame control + duration for control frames
	}

	CHECK(ours->headerLength() == theirs.header_len, "header_len " << ours->headerLength() << " vs " << theirs.header_len);
	CHECK(memcmp(ours->header().addr1.data(), theirs.header.data.addr1, 6) == 0, "addr1");
	CHECK(memcmp(ours->header().addr2.data(), theirs.header.data.addr2, 6) == 0, "addr2");
	CHECK(memcmp(ours->header().addr3.data(), theirs.header.data.addr3, 6) == 0, "addr3");
	if (theirs.len > theirs.header_len)
		CHECK(memcmp(ours->body().data(), theirs.body, ours->body().size()) == 0, "body");

	// Beacons and probe responses: everything in libwifi_bss
	if (ours->is(Wifi::ManagementSubtype::Beacon) || ours->is(Wifi::ManagementSubtype::ProbeResp))
	{
		libwifi_bss bss = {};
		const bool isBeacon = ours->is(Wifi::ManagementSubtype::Beacon);
		const int ret = isBeacon ? libwifi_parse_beacon(&bss, &theirs) : libwifi_parse_probe_resp(&bss, &theirs);
		auto mine = isBeacon ? Wifi::Beacon::parseBss(*ours) : Wifi::Probe::Response::parseBss(*ours);
		g_stats[isBeacon ? "beacons" : "probe responses"]++;

		CHECK((ret == 0) == mine.has_value(), "bss parse result");
		if (ret == 0 && mine)
		{
			CHECK(memcmp(mine->bssid.data(), bss.bssid, 6) == 0, "bssid");
			CHECK(mine->ssid == std::string(bss.ssid, strnlen(bss.ssid, 32)), "ssid '" << mine->ssid << "' vs '" << bss.ssid << "'");
			CHECK(mine->hidden == static_cast<bool>(bss.hidden), "hidden");
			CHECK(mine->channel == bss.channel, "channel " << int(mine->channel) << " vs " << int(bss.channel));
			CHECK(mine->wps == static_cast<bool>(bss.wps), "wps");
			CHECK(mine->encryptionInfo == bss.encryption_info,
				"encryption_info " << std::hex << mine->encryptionInfo << " vs " << bss.encryption_info << std::dec
				<< " (" << mine->securityTypes() << " / " << mine->akmSuites() << ")");
			CHECK(mine->tags.serialize() == std::vector<uint8_t>(bss.tags.parameters, bss.tags.parameters + bss.tags.length),
				"tags bytes");
			if (mine->rsn)
			{
				CHECK(mine->rsn->groupCipher.type == bss.rsn_info.group_cipher_suite.suite_type, "rsn group");
				CHECK(static_cast<int>(mine->rsn->akmSuites.size()) == bss.rsn_info.num_auth_key_mgmt_suites, "rsn akm count");
				CHECK(mine->rsn->capabilities == bss.rsn_info.rsn_capabilities, "rsn caps");
			}

			// libwifi's supported-rates lookup in ConnectionHandler
			libwifi_tag_iterator it = {};
			if (bss.tags.length && libwifi_tag_iterator_init(&it, bss.tags.parameters, bss.tags.length) == 0)
			{
				do
				{
					if (it.tag_header->tag_num == TAG_SUPP_RATES)
					{
						const Wifi::Tag* tag = mine->tags.find(Wifi::TagNumber::SupportedRates);
						CHECK(tag && tag->data == std::vector<uint8_t>(it.tag_data, it.tag_data + it.tag_header->tag_len), "supported rates");
						break;
					}
				} while (libwifi_tag_iterator_next(&it) != -1);
			}
		}
		libwifi_free_bss(&bss);
	}

	if (ours->is(Wifi::ManagementSubtype::Auth))
	{
		g_stats["auth"]++;
		auto auth = Wifi::Auth::parse(*ours);
		const auto* fixed = reinterpret_cast<libwifi_auth_fixed_parameters*>(theirs.body);
		CHECK(auth && static_cast<uint16_t>(auth->status) == fixed->status_code &&
			auth->transactionSequence == fixed->transaction_sequence, "auth fixed params");
	}

	if (ours->is(Wifi::ManagementSubtype::AssocResp))
	{
		g_stats["assoc responses"]++;
		auto resp = Wifi::Assoc::Response::parse(*ours);
		const auto* fixed = reinterpret_cast<libwifi_assoc_resp_fixed_parameters*>(theirs.body);
		CHECK(resp && static_cast<uint16_t>(resp->status) == fixed->status_code &&
			resp->associationId == fixed->association_id, "assoc resp fixed params");
	}

	if (ours->is(Wifi::ManagementSubtype::AssocReq))
	{
		g_stats["assoc requests"]++;
		auto req = Wifi::Assoc::Request::parse(*ours);
		CHECK(req && !req->ssid().empty(), "assoc request ssid");
	}

	if (ours->is(Wifi::ManagementSubtype::ProbeReq))
	{
		g_stats["probe requests"]++;
		libwifi_sta sta = {};
		const int ret = libwifi_parse_probe_req(&sta, &theirs);
		auto req = Wifi::Probe::Request::parse(*ours);
		CHECK(req.has_value(), "probe request parse");
		if (ret == 0 && req)
			CHECK(req->ssid() == std::string(sta.ssid, strnlen(sta.ssid, 32)), "probe request ssid");
		libwifi_free_sta(&sta);
	}

	// EAPOL
	const bool theirEapol = libwifi_check_wpa_handshake(&theirs) > 0;
	CHECK(Wifi::Wpa::isEapol(*ours) == theirEapol, "isEapol");
	if (theirEapol)
	{
		g_stats["eapol"]++;
		libwifi_wpa_auth_data wpa = {};
		const int ret = libwifi_get_wpa_data(&theirs, &wpa);
		auto key = Wifi::Wpa::EapolKey::parse(*ours);
		CHECK(ret == 0 && key, "eapol parse");
		if (ret == 0 && key)
		{
			CHECK(key->keyInformation == wpa.key_info.information, "key info");
			CHECK(key->replayCounter == wpa.key_info.replay_counter, "replay counter");
			CHECK(memcmp(key->nonce.data(), wpa.key_info.nonce, 32) == 0, "nonce");
			CHECK(memcmp(key->mic.data(), wpa.key_info.mic, 16) == 0, "mic");
			CHECK(key->keyData.size() == wpa.key_info.key_data_length &&
				(key->keyData.empty() || memcmp(key->keyData.data(), wpa.key_info.key_data, key->keyData.size()) == 0), "key data");
			CHECK(static_cast<int>(key->message()) == libwifi_check_wpa_message(&theirs), "handshake message");
			// Our bytes must rebuild exactly what was captured
			const auto eapol = ours->body().subspan(Wifi::Wpa::LLC_SNAP_EAPOL.size());
			const auto rebuilt = key->build();
			CHECK(std::equal(rebuilt.begin(), rebuilt.end(), eapol.begin()), "eapol rebuild");
			g_stats[std::string("eapol ") + Wifi::Wpa::messageName(key->message())]++;
		}
		libwifi_free_wpa_data(&wpa);
	}

	// Rebuild management frames we know from their parsed form
	if (ours->is(Wifi::ManagementSubtype::Beacon))
	{
		auto beacon = Wifi::Beacon::parse(*ours);
		CHECK(beacon && std::ranges::equal(beacon->build(), ours->bytes()), "beacon rebuild");
	}
	if (ours->is(Wifi::ManagementSubtype::ProbeResp))
	{
		auto resp = Wifi::Probe::Response::parse(*ours);
		CHECK(resp && std::ranges::equal(resp->build(), ours->bytes()), "probe response rebuild");
	}
	if (ours->is(Wifi::ManagementSubtype::AssocReq) || ours->is(Wifi::ManagementSubtype::AssocResp))
	{
		auto req = Wifi::Assoc::Request::parse(*ours);
		auto resp = Wifi::Assoc::Response::parse(*ours);
		const auto built = req ? req->build() : resp->build();
		CHECK(std::ranges::equal(built, ours->bytes()), "assoc rebuild");
	}
	if (ours->is(Wifi::ManagementSubtype::Auth))
	{
		auto auth = Wifi::Auth::parse(*ours);
		CHECK(auth && std::ranges::equal(auth->build(), ours->bytes()), "auth rebuild");
	}

	libwifi_free_wifi_frame(&theirs);
}

static void testCapture(const char* path)
{
	char err[PCAP_ERRBUF_SIZE];
	pcap_t* pcap = pcap_open_offline(path, err);
	if (!pcap)
	{
		std::cerr << "cannot open " << path << ": " << err << std::endl;
		g_failures++;
		return;
	}
	pcap_pkthdr* hdr;
	const u_char* data;
	while (pcap_next_ex(pcap, &hdr, &data) == 1)
		compareFrame(data, hdr->caplen);
	pcap_close(pcap);
}

int main(int argc, char** argv)
{
	testGenerators();
	testBuilders();
	if (argc > 1)
		testCapture(argv[1]);

	for (const auto& [name, count] : g_stats)
		std::cout << "  " << name << ": " << count << std::endl;
	std::cout << g_checks - g_failures << "/" << g_checks << " checks passed" << std::endl;
	return g_failures == 0 ? 0 : 1;
}
